inline const std::vector<Table>& all_tables() {
    static const std::vector<Table> t = [] {
        std::vector<Table> out;
        const auto add = [&out](std::string_view lang, const RawRow* rows, std::size_t nr,
                                const RawForms* forms, std::size_t nf) {
            Table one;
            one.lang = lang;
            one.rows.reserve(nr);
            for (std::size_t i = 0; i < nr; ++i) one.rows.emplace(rows[i].zh, std::string(rows[i].said));
            for (std::size_t i = 0; i < nf; ++i) {
                Forms f;
                for (std::size_t k = 0; k < f.size(); ++k) f[k] = std::string(forms[i].f[k]);
                one.plurals.emplace(forms[i].zh, std::move(f));
            }
            out.push_back(std::move(one));
        };
        add("ar", kRows_ar, std::size(kRows_ar), kForms_ar, std::size(kForms_ar));
        add("de", kRows_de, std::size(kRows_de), kForms_de, std::size(kForms_de));
        add("en", kRows_en, std::size(kRows_en), kForms_en, std::size(kForms_en));
        add("es", kRows_es, std::size(kRows_es), kForms_es, std::size(kForms_es));
        add("fr", kRows_fr, std::size(kRows_fr), kForms_fr, std::size(kForms_fr));
        add("hi", kRows_hi, std::size(kRows_hi), kForms_hi, std::size(kForms_hi));
        add("ja", kRows_ja, std::size(kRows_ja), kForms_ja, std::size(kForms_ja));
        add("ko", kRows_ko, std::size(kRows_ko), kForms_ko, std::size(kForms_ko));
        add("pt_BR", kRows_pt_BR, std::size(kRows_pt_BR), kForms_pt_BR, std::size(kForms_pt_BR));
        add("ru", kRows_ru, std::size(kRows_ru), kForms_ru, std::size(kForms_ru));
        add("zh_TW", kRows_zh_TW, std::size(kRows_zh_TW), kForms_zh_TW, std::size(kForms_zh_TW));
        return out;
    }();
    return t;
}

#define kTables (all_tables())
